            guard let a0 = args[0].string else { return settle.reject("bad arguments — RtcPeerConnection.setBufferedAmountLowThreshold: channelId") }
            guard let a1 = args[1].f64 else { return settle.reject("bad arguments — RtcPeerConnection.setBufferedAmountLowThreshold: threshold") }
            plugin.setBufferedAmountLowThreshold(a0, a1, Reply<Void, RtcPeerConnectionCode>(settle))
        case "closeDataChannel":
            guard let a0 = args[0].string else { return settle.reject("bad arguments — RtcPeerConnection.closeDataChannel: channelId") }
            plugin.closeDataChannel(a0, Reply<Void, RtcPeerConnectionCode>(settle))
        default:
            settle.reject("Unknown method: \(method)")
        }
    }

    func close() { plugin.close() }
}

// MARK: - RtcVideo

/// The codes the calls of "rtcVideo" reject with.
public enum RtcVideoCode: String, PluginCode {
    case notFound
}

/// The events of "rtcVideo": what the plugin sends the app. Any thread.
public struct RtcVideoEvents {
    let channel: NativeViewChannel

    /// The first frame was drawn, and every change of the picture's size after.
    public func resize(width: Int32, height: Int32) {
        self.channel.emit("resize") { w in
            w.beginObject(2)
            w.key("width"); w.i32(width)
            w.key("height"); w.i32(height)
            w.end()
        }
    }
}

/// A view drawing one video track, local or remote.
/// What the plugin implements. A call arrives on the main thread; its reply is settled exactly
/// once, now or later, from any thread.
public protocol RtcVideoPlugin: AnyObject {
    /// The view the host mounts: fullscreen, or embedded among a screen's children.
    var view: UIView { get }

    /// Draw another track; null = black.
    /// Rejects with .notFound.
    func setTrack(_ trackId: String?, _ reply: Reply<Void, RtcVideoCode>)
    func setObjectFit(_ fit: ObjectFit, _ reply: Reply<Void, RtcVideoCode>)
    func setMirror(_ mirror: Bool, _ reply: Reply<Void, RtcVideoCode>)

    /// The instance goes (the world swapped): release the hardware.
    func destroy()
}

public extension RtcVideoPlugin {
    func destroy() {}
}

public enum RtcVideoChannel {
    /// What the halves register under.
    public static let name = "rtcVideo"
    /// The contract's version: the highest `@since` of its members.
    public static let version = 1

    /// Register the view: `make` builds one instance from its params.
    public static func register(in engine: LeCodesEngine, _ make: @escaping (RtcVideoParams, RtcVideoEvents) -> RtcVideoPlugin) {
        engine.registerView(name, version: Int32(version)) { params, channel in
            RtcVideoGlue(make(WireIn.of(params, { RtcVideoParams(wire: $0) }) ?? RtcVideoParams(), RtcVideoEvents(channel: channel)))
        }
    }
}

/// Reads a call off the wire and hands it to the plugin; a malformed call never reaches it.
final class RtcVideoGlue: WireNativeViewInstance {
    private let plugin: RtcVideoPlugin

    init(_ plugin: RtcVideoPlugin) { self.plugin = plugin }

    var view: UIView { plugin.view }

    func call(_ method: String, wire args: WireIn, _ settle: ChannelSettle) {
        switch method {
        case "setTrack":
            let w0 = args[0]
            var a0: String? = nil
            if w0.isPresent {
                guard let v = w0.string else { return settle.reject("bad arguments — RtcVideo.setTrack: trackId") }
                a0 = v
            }
            plugin.setTrack(a0, Reply<Void, RtcVideoCode>(settle))
        case "setObjectFit":
            guard let a0 = ObjectFit(wire: args[0]) else { return settle.reject("bad arguments — RtcVideo.setObjectFit: fit") }
            plugin.setObjectFit(a0, Reply<Void, RtcVideoCode>(settle))
        case "setMirror":
            guard let a0 = args[0].bool else { return settle.reject("bad arguments — RtcVideo.setMirror: mirror") }
            plugin.setMirror(a0, Reply<Void, RtcVideoCode>(settle))
        default:
            settle.reject("Unknown method: \(method)")
        }
    }

    func destroy() { plugin.destroy() }
}
